{"file_path":"src/parser.js","content":"const newTable = () => ({ t: 'table', map: new Map(), headerDefined: false })
const scalar = (type, v) => ({ t: 'scalar', type, v })

class Fail extends Error {
  constructor(msg) {
    super(msg)
    this.tomlError = true
  }
}
const fail = (m) => {
  throw new Fail(m)
}

const NAME_CH = /[A-Za-z0-9_-]/
const isWs = (c) => c === ' ' || c === '\t'
const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

class LineParser {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  ws() {
    while (this.i < this.s.length && isWs(this.s[this.i])) this.i++
  }
  // end of the meaningful part of the line
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  basicString() {
    const s = this.s
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= s.length) fail('unterminated string')
      const c = s[this.i]
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        if (this.i + 1 >= s.length) fail('unterminated string')
        const e = s[this.i + 1]
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) {
          out += map[e]
          this.i += 2
        } else if (e === 'u') {
          const h = s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 6
        } else {
          const cp = String.fromCodePoint(s.codePointAt(this.i + 1))
          fail(`invalid escape \\${cp}`)
        }
      } else {
        out += c
        this.i++
      }
    }
  }
  literalString() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) fail('unterminated string')
    const out = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return out
  }
  name() {
    const c = this.s[this.i]
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    const st = this.i
    while (this.i < this.s.length && NAME_CH.test(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const names = []
    this.ws()
    names.push(this.name())
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] === '.') {
        this.i++
        this.ws()
        names.push(this.name())
      } else {
        this.i = save
        return names
      }
    }
  }
  value(base, inInline) {
    this.ws()
    const c = this.s[this.i]
    if (this.atEnd() || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"') return scalar('string', this.basicString())
    if (c === "'") return scalar('string', this.literalString())
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.s[this.i]) && !',]};'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return scalar('boolean', w === 'true')
    if (INT.test(w)) return scalar('integer', Number(w.replace(/_/g, '')))
    if (FLOAT.test(w)) return scalar('float', Number(w.replace(/_/g, '')))
    fail(`invalid value ${w}`)
  }
  array(base) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.s[this.i] === ']') {
        this.i++
        break
      }
      if (this.atEnd()) fail('unterminated array')
      items.push(this.value(base))
      this.ws()
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === ']') {
        this.i++
        break
      } else if (this.atEnd()) fail('unterminated array')
      else fail('trailing text after a value')
    }
    return { t: 'array', items, aot: false }
  }
  inline(base) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.s[this.i] === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.s[this.i] !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value(base)
      assign(tbl, base, names, v)
      this.ws()
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === '}') {
        this.i++
        return tbl
      } else if (this.atEnd()) fail('unterminated inline table')
      else fail('trailing text after a value')
    }
  }
}

function walk(table, path, names) {
  let cur = table
  const p = [...path]
  for (const n of names) {
    p.push(n)
    let child = cur.map.get(n)
    if (!child) {
      child = newTable()
      cur.map.set(n, child)
    }
    if (child.t === 'array' && child.aot) child = child.items[child.items.length - 1]
    else if (child.t !== 'table') fail(`${p.join('.')} is not a table`)
    cur = child
  }
  return { table: cur, path: p }
}

function assign(table, path, names, value) {
  const w = walk(table, path, names.slice(0, -1))
  const last = names[names.length - 1]
  const full = [...w.path, last].join('.')
  if (w.table.map.has(last)) fail(`key ${full} is defined twice`)
  w.table.map.set(last, value)
}

function header(p, state) {
  const dbl = p.s[p.i + 1] === '['
  p.i += dbl ? 2 : 1
  const names = p.dotted()
  p.ws()
  if (p.s[p.i] !== ']') fail('unterminated table header')
  p.i++
  if (dbl) {
    if (p.s[p.i] !== ']') fail('unterminated table header')
    p.i++
  }
  p.ws()
  if (!p.atEnd()) fail('trailing text after a table header')
  const w = walk(state.root, [], names.slice(0, -1))
  const last = names[names.length - 1]
  const full = [...w.path, last].join('.')
  const ex = w.table.map.get(last)
  if (dbl) {
    const fresh = newTable()
    if (!ex) w.table.map.set(last, { t: 'array', items: [fresh], aot: true })
    else if (ex.t === 'array' && ex.aot) ex.items.push(fresh)
    else fail(`${full} is not an array of tables`)
    state.cur = fresh
    state.path = [...w.path, last]
  } else {
    let t
    if (!ex) {
      t = newTable()
      w.table.map.set(last, t)
    } else if (ex.t === 'table') {
      if (ex.headerDefined) fail(`table ${full} is defined twice`)
      t = ex
    } else fail(`${full} is not a table`)
    t.headerDefined = true
    state.cur = t
    state.path = [...w.path, last]
  }
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  const state = { root, cur: root, path: [] }
  for (let n = 0; n < lines.length; n++) {
    try {
      const line = lines[n]
      const p = new LineParser(line)
      p.ws()
      const c = line[p.i]
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') {
        header(p, state)
        continue
      }
      const names = p.dotted()
      p.ws()
      if (line[p.i] !== '=') fail('expected key = value')
      p.i++
      const full = [...state.path, ...names]
      const v = p.value(state.path)
      p.ws()
      if (!p.atEnd()) fail('trailing text after a value')
      assign(state.cur, state.path, names, v)
      void full
    } catch (e) {
      if (e && e.tomlError) e.line = n + 1
      throw e
    }
  }
  return root
}
"}

